from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field, condecimal, confloat, conbool, root_validator
from decimal import Decimal, getcontext, ROUND_HALF_UP

getcontext().rounding = ROUND_HALF_UP  # Set the rounding method to match financial rounding standards

app = FastAPI()

class ShippingRequest(BaseModel):
    weightKg: condecimal(gt=Decimal('0'), le=Decimal('30')) = Field(..., description="Weight of the package in kilograms. Must be greater than 0 and less than or equal to 30.")
    zone: str = Field(..., description="Shipping zone. Must be 'local' or 'remote'.")
    insured: bool = Field(False, description="Whether the package is insured. Default is False.")

    @root_validator(pre=True)
    def validate_zone_and_insured(cls, values):
        if 'zone' in values and values['zone'] not in ['local', 'remote']:
            raise ValueError("Zone must be 'local' or 'remote'")
        if 'insured' in values and not isinstance(values['insured'], bool):
            raise ValueError("Insured must be a boolean value")
        return values

@app.post('/shipping-quote')
async def shipping_quote(request: ShippingRequest):
    base_fee = Decimal('5.00') if request.zone == 'local' else Decimal('12.00')
    additional_weight = max(Decimal('0'), (request.weightKg - Decimal('1')).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    fee = base_fee + additional_weight * Decimal('2.00')
    if request.insured:
        fee += Decimal('3.00')
    return {'fee': f'{fee:.2f}'}

@app.get('/health')
async def health_check():
    return {'status': 'ok'}

