    zone: str = Field(..., description="Shipping zone. Must be 'local' or 'remote'.")
    insured: bool = Field(False, description="Whether the package is insured. Default is False.")

    @root_validator(pre=True)
    def validate_zone(cls, values):
        if 'zone' in values and values['zone'] not in ['local', 'remote']:
            raise ValueError("Zone must be 'local' or 'remote'")
        return values

@app.post('/shipping-quote')
async def shipping_quote(request: ShippingRequest):
    base_fee = Decimal('5.00') if request.zone == 'local' else Decimal('12.00')
    additional_weight = max(Decimal('0'), (request.weightKg - Decimal('1')).to_integral_exact(rounding=ROUND_HALF_UP))
    fee = base_fee + additional_weight * Decimal('2.00')
    if request.insured:
        fee += Decimal('3.00')
