from app.shipping_api import app
import pytest

client = TestClient(app)

def test_valid_local_quote():
    response = client.post('/shipping-quote', json={'weightKg': '2.5', 'zone': 'local'})
    assert response.status_code == 200
    assert response.json() == {'fee': '5.00'}

def test_valid_remote_quote():
    response = client.post('/shipping-quote', json={'weightKg': '10.5', 'zone': 'remote', 'insured': True})
    assert response.status_code == 200
    assert response.json() == {'fee': '23.00'}

def test_invalid_weight_quote():
    response = client.post('/shipping-quote', json={'weightKg': '-1', 'zone': 'local'})
    assert response.status_code == 422

