    response = client.post('/shipping-quote', json={'weightKg': '5', 'zone': 'invalid'})
    assert response.status_code == 422

def test_extra_fields_quote():
    response = client.post('/shipping-quote', json={'weightKg': '5', 'zone': 'local', 'extra': 'field'})
    assert response.status_code == 422

def test_health_check():
    response = client.get('/health')
    assert response.status_code == 200
    assert response.json() == {'status': 'ok'}

