from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from datetime import datetime

app = FastAPI()

class BookingCheck(BaseModel):
    date: str
    startMinute: int
    endMinute: int
    seats: int

@app.get('/health')
async def health():
    return {'status': 'ok'}

@app.post('/booking-check')
async def booking_check(booking: BookingCheck):
    try:
        # Validate date format
        datetime.strptime(booking.date, '%Y-%m-%d')
        if not (0 <= booking.startMinute < booking.endMinute <= 1440):
            raise ValueError('Invalid start or end minute.')
        if booking.startMinute % 15 != 0 or booking.endMinute % 15 != 0:
            raise ValueError('Start and end minutes must be multiples of 15.')
        if not (15 <= booking.endMinute - booking.startMinute <= 180):
            raise ValueError('Duration must be between 15 and 180 minutes.')
        if not (1 <= booking.seats <= 8):
            raise ValueError('Number of seats must be between 1 and 8.')

        duration_minutes = booking.endMinute - booking.startMinute
        seat_minutes = duration_minutes * booking.seats

        return {
            'date': booking.date,
            'durationMinutes': duration_minutes,
            'seatMinutes': seat_minutes
        }
    except ValueError as e:
        raise HTTPException(status_code=422, detail=str(e))

